// Native game-specific geometry composition. Each part resolves to authored text.
export function createFighterArtState(fighter) {
  return { parts: fighter.initialParts.map(p => [...p]), origin: [...fighter.initialOrigin],
    anchor: [...fighter.initialAnchor], pose: fighter.initialPose, rowHeight: fighter.rowHeight, bank: fighter.initialBank };
}
export function advanceFighterArt(fighter, state, {pose, flags = 128, spriteMode = 0, rowHeight = fighter.rowHeight, x = state.anchor[0], y = state.anchor[1]}) {
  if (!flags) return state;
  const full = spriteMode ? fighter.normalModes[pose] : fighter.normalParts[pose];
  if (pose < 128 && (flags & 128)) {
    if (!full) throw Error('Missing complete fighter text pose ' + pose);
    const dx = x - fighter.anchor[0], dy = y - fighter.anchor[1];
    const writes = rowHeight === fighter.rowHeight ? fighter.normalWrites : fighter.alternateNormalWrites;
    for (const [index,field,value,relative] of writes[pose][spriteMode ? 1 : 0]) {
      state.parts[index][field] = relative ? (value + (field===0?dy:dx)) & 255 : value;
    }
    state.origin = [...full.origin];
  } else {
    const recipe = fighter.recipes[pose];
    if (pose < 128) {
      if (!full) throw Error('Missing fighter movement descriptor ' + pose);
      state.origin = [...full.origin];
    } else if (!recipe) throw Error('Missing incremental fighter text recipe ' + pose);
    else if (recipe.origin) state.origin = [...recipe.origin];
    const dx = ((state.origin[0] + x) - state.parts[0][3]) & 255;
    const dy = ((state.origin[1] + y) - state.parts[0][0]) & 255;
    if (dy) for (let i = 0; i < Math.min(60, state.parts.length); i++) {
      if (i >= 32 && state.parts[i][0] >= 248) break;
      state.parts[i][0] = (state.parts[i][0] + dy) & 255;
    }
    if (dx) for (let i = 0; i < Math.min(60,state.parts.length); i++) state.parts[i][3] = (state.parts[i][3] + dx) & 255;
    if (flags & 128) {
      const writes = recipe.modes[spriteMode ? 1 : 0];
      if (!writes) throw Error('Original incremental art descriptor unsupported: ' + pose);
      for (const [index, field, value] of writes) state.parts[index][field] = value;
    }
  }
  // $D043: after position-only or C0-range changes, move sprite priority across
  // the fight-area boundary. Stop at the first already-behind sprite exactly.
  if (!(flags & 128) || pose >= 192) {
    let i = 0;
    while (i < state.parts.length && state.parts[i][0] < 80) { state.parts[i][2] &= 223; i++; }
    while (i < state.parts.length && !(state.parts[i][2] & 32)) { state.parts[i][2] |= 32; i++; }
  }
  // Original D29B can select a different CHR bank in the pose's tile stream.
  // Position-only redraws and descriptors without that write retain the bank.
  if(flags&128){const bank=pose<128?fighter.normalBankWrites?.[pose]?.[spriteMode?1:0]:fighter.recipes[pose]?.bankWrites?.[spriteMode?1:0];if(bank!==null&&bank!==undefined)state.bank=bank;}
  state.anchor = [x, y]; state.pose = pose; state.rowHeight = rowHeight;
  return state;
}
const starMatrices=new Map();
function committedStarPart({oam:p,rowHeight}){
  if(p[0]>=240)return null;
  const key=rowHeight+'/'+p[1]+'/'+(p[2]&192),glyph=STAR_ART[key];
  if(!glyph)return null;
  const palette=(p[2]&3)*4,cacheKey=key+'/'+palette;
  if(!starMatrices.has(cacheKey))starMatrices.set(cacheKey,{...glyph,inks:glyph.inks.map(row=>[...row].map(ink=>ink==='.'?'.':(parseInt(ink,36)+palette).toString(36)).join(''))});
  return {x:p[3],y:p[0]+1,foreground:!(p[2]&32),matrix:starMatrices.get(cacheKey)};
}
export function fighterArtParts(fighter, state, starSprite=null) {
  const banks = state.rowHeight === fighter.rowHeight ? fighter.bankGlyphs : fighter.alternateBankGlyphs;
  const glyphs = banks ? banks[state.bank] : state.rowHeight === fighter.rowHeight ? fighter.glyphs : fighter.alternateGlyphs;
  if(!glyphs)throw Error('Missing opponent graphics bank '+state.bank);
  return state.parts.map((p,index) => index===60&&starSprite?committedStarPart(starSprite):({ x: p[3], y: p[0] + 1, foreground: !(p[2] & 32), matrix: p[0] < 240 ? glyphs[p[1] + '/' + (p[2] & 195)] : null }))
    .filter(p => p?.matrix).reverse();
}
export function createPlayerArtState(pose = null) {
  // Original drawing streams are incremental nametable writes. Bout setup
  // starts clear and uploads its own opening pose; preloading pose 0 leaves
  // an extra Mac because the opening stream never erases that invented pose.
  const state={tiles:new Map(),owners:new Map(),pose:null};
  return pose===null?state:advancePlayerArt(state,pose);
}
export function advancePlayerArt(state, pose) {
  const stream = PLAYER_ART.streams[pose];
  if (!stream) throw Error('Missing Little Mac/referee drawing stream ' + pose);
  state.owners??=new Map();
  for (const [address, tile] of stream) {state.tiles.set(address, tile);state.owners.set(address,pose);}
  state.pose = pose; return state;
}
export function playerArtParts(state, scrollX = 432) {
  const project = address => {
    const nt=(address-8192)&1023;
    let x=((((address-8192)>>>10)&1)*256+(nt&31)*8-scrollX+512)&511;
    if(x>=504)x-=512;
    return {x,y:(nt>>5)*8};
  };
  const suppressed=new Set(),hidden=new Set(),labels=[];
  for(const pattern of PLAYER_ART.letteringPatterns??[])for(const [address,tile]of state.tiles){
    if(tile!==pattern.tiles[0][2]||!pattern.tiles.every(([dx,dy,t])=>state.tiles.get(address+dx+dy*32)===t))continue;
    const point=project(address);point.x+=pattern.offsetX??0;if(point.x>=256||point.y>=240)continue;
    for(const [dx,dy]of pattern.tiles)(pattern.hideTiles?hidden:suppressed).add(address+dx+dy*32);
    labels.push({...point,matrix:{width:0,height:0,rows:[],inks:[],lettering:{text:pattern.text,width:pattern.width,fontSize:pattern.fontSize,scaleX:pattern.scaleX,ink:PLAYER_ART.attributes[address]+pattern.inkOffset}}});
  }
  const parts=[...state.tiles].map(([address,tile])=>{
    let matrix=PLAYER_ART.glyphs[tile+'/'+PLAYER_ART.attributes[address]];
    if(matrix?.speech?.allowedPoses.includes(state.owners?.get(address)))matrix=matrix.speech;
    if(hidden.has(address))matrix=null;
    else if(suppressed.has(address)&&matrix?.lettering){const {lettering,...cloud}=matrix;matrix=cloud;}
    return {...project(address),matrix};
  }).filter(p=>p.x<256&&p.y<240&&p.matrix?.width);
  return parts.concat(labels);
}
